const items = $input.all();

const row = items
  .map(item => item.json)
  .find(row => row.account_id);

const requestedAccountId = $('When Executed by Another Workflow')
  .first()
  .json.account_id.trim();

if (!row) {
  return [
    {
      json: {
        account_id: requestedAccountId,
        found: false,
        account: null,
      },
    },
  ];
}

const owner = row.owner_sales_user_id
  ? {
      sales_user_id: row.owner_sales_user_id,
      name: row.owner_name,
      role: row.owner_role,
      territory: row.owner_territory,
      status: row.owner_status,
    }
  : null;

return [
  {
    json: {
      account_id: requestedAccountId,
      found: true,
      account: {
        account_id: row.account_id,
        account_name: row.account_name,
        segment: row.segment,
        account_tier: row.account_tier,
        account_status: row.account_status,
        customer_since: row.customer_since,
        sales_territory: row.sales_territory,
        owner,
      },
    },
  },
];

return {
  json: {
    error: {
      code: "INVALID_INPUT",
      message: "account_id must be a non-empty string"
    }
  }
};
